/// Traductions connues pour un identifiant local de move.
///
/// Renvoie une map vide quand le move est inconnu de la table,
/// ce qui laisse le libellé anglais canonique en place.
Map<String, String> localizedNamesForMove(String localId) =>
    pokemonMoveLocalizedNames[localId] ?? const <String, String>{};
